head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf73020";
scwin.editor = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"authYn":"Y"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — pageContext.ldMktTpCd, pageContext.psDepCd, ipt_updateYn, insertYn

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_ldMktTpCd", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610'); } }, { id: "if_ldMktTpCd_2", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410'); } }, { id: "if_ldMktTpCd_3", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2'); } }, { id: "btn_save", fn: function(){ return (((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2')); } }, { id: "btn_delete", fn: function(){ return (((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2')); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_relLawDtlNo", fn: function () { return String(String((dma_pageContext.get("relLawDtlNo") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        frame.Title = "단위조항 변경";
        if ((String(((dma_pageContext.get("ipt_updateYn") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_updateYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ipt_updateYn") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_updateYn") ?? "")))) === 'Y') {
            await $c.win.alert("변경되었습니다.");
        } else {
            if ((String(((dma_pageContext.get("insertYn") ?? "")) == null ? '' : ((dma_pageContext.get("insertYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("insertYn") ?? "")) == null ? '' : ((dma_pageContext.get("insertYn") ?? "")))) === 'Y') {
                await $c.win.alert("등록되었습니다.");
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf73020.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_save();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.editor =new Dext5editor("dext5editor1"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf73020' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf73020.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name relLawDtlForm_onsubmit
 * @description relLawDtlForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.relLawDtlForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf73020.relLawDtlForm_onsubmit' }); }
};

/**
 * @method
 * @name ipt_relLawDtlNm_onchange
 * @description ipt_relLawDtlNm 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_relLawDtlNm_onchange = function(e){
    try {
        scwin.changeText();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf73020.ipt_relLawDtlNm_onchange' }); }
};

/**
 * @method
 * @name input_35_onclick
 * @description 「중복확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_35_onclick = async function(e){
    try {
        await scwin.tx_fn_chkDup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf73020.input_35_onclick' }); }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「변경」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function(e){
    try {
        await scwin.save()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf73020.btn_save_onclick' }); }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_delete_onclick = async function(e){
    try {
        await scwin.tx_fn_delete()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf73020.btn_delete_onclick' }); }
};

/**
 * @method
 * @name btn_closeFrame_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_closeFrame_onclick = function(e){
    try {
        scwin.closeFrame()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf73020.btn_closeFrame_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_save
 * @description save 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_save = async function () {
    const sbmOptions = {
        id: "tx_fn_save",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_saveReq",
        target: "dlt_junmoonList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_chkDup
 * @description chk Dup 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_chkDup = async function () {
    const sbmOptions = {
        id: "tx_fn_chkDup",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_chkDupReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_delete
 * @description delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_delete = async function () {
    const sbmOptions = {
        id: "tx_fn_delete",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_deleteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name closeFrame
 * @description close Frame 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeFrame = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    $c.win.closePopup();
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    if ($c.util.getComponent('ipt_dupChkYn').getValue() !== 'Y' && !$('#dupBtn').hasClass("bt2")) {
        await $c.win.alert("단위조항 중복확인 후 저장이 가능합니다.");
        return;
    }
    let sprtRoomNo = $('#slc_junmoon option:selected').val();
    if (sprtRoomNo.length === 0) {
        await $c.win.alert("법규전문을 선택해 주시기 바랍니다.");
        return;
    }
    if (!await $c.win.confirm("저장하시겠습니까?")) {
        return;
    }
    sprtRoomNo = sprtRoomNo.split("_")[0];
    $c.util.getComponent('ipt_sprtRoomNo').setValue(sprtRoomNo);
    $c.util.getComponent('ipt_updateYn').setValue("Y");
    $c.util.getComponent('ipt_relLawDtlContn').setValue(DEXT5.getBodyValue("dext5editor1"));
    await scwin.tx_fn_save();
};

/**
 * @method
 * @name changeText
 * @description change Text 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeText = function () {
    $c.util.getComponent('ipt_dupChkYn').setValue("N");
    setBtnEnable($('#dupBtn'));
};

/**
 * @method
 * @name dext_editor_loaded_event
 * @description dext editor loaded event 처리
 * @returns {void}
 * @hidden N
 */
scwin.dext_editor_loaded_event = function () {
    DEXT5.setBodyValue($c.util.getComponent('ipt_relLawDtlContn').getValue(), "dext5editor1");
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
